document.addEventListener("DOMContentLoaded",function(){const t=document.querySelectorAll(".rpt-lazyload, .lazy-load");if("IntersectionObserver"in window){const e=new IntersectionObserver(function(t,e){t.forEach(function(t){if(t.isIntersecting){const n=t.target;let o="";n.classList.contains("rpt-lazyload")?(o=n.dataset.bg,n.style.backgroundImage="url("+o+")"):n.classList.contains("lazy-load")&&(o=n.dataset.src,n.src=o),n.classList.remove("rpt-lazyload","lazy-load"),e.unobserve(n)}})});t.forEach(function(t){e.observe(t)})}});